input_grid = [
    [2, 3, 3, 4],
    [3, 0, 3, 3],
    [2, 3, 3, 3],
    [2, 2, 0, 3],
    [2, 3, 1, 3],
    [1, 3, 4, 3],
    [3, 3, 3, 1],
    [3, 3, 4, 4]
]

top_core = [
    [4, 4, 3, 3],
    [1, 3, 3, 3],
    [3, 4, 3, 1],
    [3, 1, 3, 2],
    [3, 0, 2, 2],
    [3, 3, 3, 2],
    [3, 3, 0, 3],
    [4, 3, 3, 2]
]

# Let me check: what if we take the UNION of two input rows (element-wise max, but 3 is transparent)?
# And the result gets shifted somehow?

print("Testing union operations (transparent background):")
def transparent_max(a, b):
    """Element-wise max, but 3 is transparent (passes through)"""
    return [b if a == 3 else a if b == 3 else max(a, b) for a, b in zip(a, b)]

def transparent_min(a, b):
    """Element-wise min, but 3 is transparent"""
    return [a if a == 3 else b if b == 3 else min(a, b) for a, b in zip(a, b)]

def transparent_or(a, b):
    """Element-wise OR: if either is non-3 and non-2, take the max of non-3 values"""
    return [0 if a==3 and b==3 else max(a if a!=3 else b, b if b!=3 else a) for a, b in zip(a, b)]

# Actually, let me just check if each core row equals some combination of pairs
print("\n\nChecking each core row against all possible row pairs:")
def try_combine(r1, r2, op_name):
    """Try to see if combining two rows gives the target"""
    if op_name == "max":
        return [max(a, b) for a, b in zip(r1, r2)]
    elif op_name == "min":
        return [min(a, b) for a, b in zip(r1, r2)]
    elif op_name == "xor_mod5":
        return [(a ^ b) % 5 for a, b in zip(r1, r2)]
    elif op_name == "sum_mod5":
        return [(a + b) % 5 for a, b in zip(r1, r2)]
    return None

# Check if any simple operation works
for r in range(8):
    target = top_core[r]
    found_op = None

    # Check all same-row operations
    for i in range(8):
        if try_combine(input_grid[r], input_grid[i], "max", "target") == target:
            found_op = f"max with row {i}"
            break
        if try_combine(input_grid[r], input_grid[i], "min", "target") == target:
            found_op = f"min with row {i}"
            break
        if try_combine(input_grid[r], input_grid[i], "xor_mod5", "target") == target:
            found_op = f"xor_mod5 with row {i}"
            break

    # Check all different-row operations  
    for i in range(8):
        if try_combine(input_grid[i], input_grid[(i+4)%8], "max", "target") == target:
            found_op = f"row {i} vs {i+4} max"
            break
    if not found_op:
        for i in range(8):
            for j in range(8):
                if i != j:
                    r1, r2 = input_grid[i], input_grid[j]
                    # Check all ops
                    ops = [("max",), ("min",), ("xor_mod5",), ("sum_mod5",)]
                    for opnames in ops:
                        result = try_combine(r1, r2, *opnames)
                        if result == target:
                            found_op = f"row {i} {opname} row {j}"
                            break
                    if found_op:
                        break
    print(f"Core row {r} ({target}): {found_op if found_op else 'NO SIMPLE OP FOUND'}")

